code.java:
class Solution {
    public int minCostToMoveChips(int[] position){
        int even=0,odd=0;
        for(int value:position)if(value%2==0)even++;
        else odd++;
        return Math.min(even,odd);
    }
}

code.kotlin:
class Solution {
    fun minCostToMoveChips(position:IntArray):Int{
        var even=0;
        var odd=0;
        for(value in position)if(value%2==0)even++ else odd++;
        return minOf(even,odd)
    }
}

code.cpp:
class Solution {
    public: int minCostToMoveChips(vector<int>& position){
        int even=0,odd=0;
        for(int value:position)value%2?++odd:++even;
        return min(even,odd);
    }
};
